    completeUploadedFile: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Upload session id (server-minted UUID). */
                id: components["parameters"]["UploadSessionId"];
                /** @description Client-chosen file id (alphanumeric, dash, underscore). */
                fileId: components["parameters"]["FileId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    totalChunks: number;
                    /** @description Safe relative path (no absolute paths, no dot segments, forward slashes). The reassembled file lands under its final relative path. */
                    relativePath: string;
                };
            };
        };
        responses: {
            /** @description File reassembled. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        fileName: string;
                        /** Format: int64 */
                        size: number;
                    };
                };
            };
            /** @description Invalid input, or a chunk is missing (message carries the missing index). */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            /** @description Reassembled file exceeds the 1 GiB cap. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
